import {calendarLabel} from './progression.mjs';
import {SECTORS,normalizeFinance} from './economy.mjs';
import {setupAudio} from './audio.mjs';
export function setupUpgradeUI({getCity,modal,toast,refresh,serialize,deserialize,loadCity,getPlaying}){
 const $=id=>document.getElementById(id),nav=document.querySelector('nav');
 const button=(id,title,fn)=>{const b=document.createElement('button');b.id=id;b.textContent=title;b.onclick=fn;nav.prepend(b);};
 button('renderer-toggle',localStorage.getItem('sc2020-renderer')==='deck'?'Use Three.js graphics':'Use deck.gl analytics renderer',()=>{localStorage.setItem('sc2020-renderer',localStorage.getItem('sc2020-renderer')==='deck'?'three':'deck');sessionStorage.setItem('sc2020-resume-renderer','1');location.reload();});
 button('budget-open','Taxes & tolls',()=>{
  const c=getCity(),f=normalizeFinance(c);
  modal('<h2>City budget</h2><p>Balance sector taxes, high-value property surcharges and tolls against voter approval.</p><div id="sector-rates"></div><label>High-value surcharge <input id="progressive-tax" type="range" min="0" max="8" step=".5"><output id="progressive-label"></output></label><label>Toll price <input id="toll-price" type="range" min="0" max="10" step=".25"><output id="toll-label"></output></label><div id="budget-ledger" class="readout"></div><p class="modal-note">Toll receipts use an estimated monthly traffic volume with price sensitivity, not measured individual trips. Maintenance changes infrastructure condition gradually. Higher land values incur up to the chosen surcharge.</p>');
  const update=()=>{refresh();const l=c.metrics.ledger;$('budget-ledger').replaceChildren();for(const [key,value]of Object.entries(l)){const row=document.createElement('p');row.textContent=`${key}: $${Math.round(value).toLocaleString()}`;$('budget-ledger').append(row);}const row=document.createElement('p');row.textContent=`Approval ${c.metrics.approval}% · Infrastructure ${c.metrics.condition}%`;$('budget-ledger').append(row);};
  for(const s of SECTORS){const label=document.createElement('label');label.textContent=s[0].toUpperCase()+s.slice(1)+' tax ';const input=document.createElement('input'),out=document.createElement('output');input.type='range';input.min=0;input.max=25;input.step=.5;input.value=f.rates[s];out.textContent=input.value+'%';input.oninput=()=>{f.rates[s]=+input.value;out.textContent=input.value+'%';update();};label.append(input,out);$('sector-rates').append(label);}
  for(const [id,key,label]of [['progressive-tax','progressive','progressive-label'],['toll-price','toll','toll-label']]){const el=$(id);el.value=f[key];$(label).textContent=el.value;el.oninput=()=>{f[key]=+el.value;$(label).textContent=el.value;update();};}update();
 });
 button('games-open','Saved cities',async()=>{
  modal('<h2>Saved cities</h2><label>Name this checkpoint <input id="checkpoint-name" maxlength="80"></label><button id="checkpoint-save">Save new checkpoint</button><p id="database-status" role="status">Reading saved cities…</p><div id="game-list"></div><p class="modal-note">Each checkpoint is independent. Docker stores these in its persistent volume. JSON export/import remains available from Save and Load.</p>');$('checkpoint-name').value=getCity().name+' · '+calendarLabel(getCity());
  const list=async()=>{try{const response=await fetch('/api/games');if(!response.ok)throw Error();const games=await response.json();$('game-list').replaceChildren();$('database-status').textContent=games.length+' SQLite checkpoints';for(const g of games){const b=document.createElement('button');b.textContent=`${g.name} · ${g.population.toLocaleString()} residents`;b.onclick=async()=>{try{const r=await fetch('/api/games/'+encodeURIComponent(g.id));if(!r.ok)throw Error('Checkpoint unavailable');const city=deserialize(JSON.stringify(await r.json()));loadCity(city);$('modal').close();toast('Checkpoint loaded.');}catch(e){toast(e.message);}};$('game-list').append(b);}}catch{$('database-status').textContent='Database unavailable. Start using Docker Compose or python server/server.py. JSON saves still work.';}};
  $('checkpoint-save').onclick=async()=>{const b=$('checkpoint-save');b.disabled=true;try{const c=getCity(),r=await fetch('/api/games',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('checkpoint-name').value,save:JSON.parse(serialize(c)),population:c.metrics.population})});const result=await r.json();if(!r.ok)throw Error(result.error||'Save failed');await list();toast('Checkpoint committed to SQLite.');}catch(e){toast('Could not save checkpoint: '+e.message);}finally{b.disabled=false;}};await list();
 });
 for(const id of ['models-open','scene-open'])document.getElementById(id)?.addEventListener('click',e=>{if(localStorage.getItem('sc2020-renderer')!=='deck'){e.stopImmediatePropagation();toast('Switch to the deck.gl analytics renderer from this menu to use imported models or I3S.');}},{capture:true});
 setupAudio({getCity,getPlaying,modal,button,toast});
}
